"""YAML renderer — standard library only (uses repr-based output)."""

from plugins import PluginError, Renderer, register


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")

        lines: list[str] = []
        for row in rows:
            lines.append("-")
            for key in sorted(row):
                val = row[key]
                if isinstance(val, str) and ("\n" in val or val.startswith((" ", "'", '"', "{", "[", "&", "*", "?", "|", ">", "%", "@", "`"))):
                    lines.append(f"  {key}: >-\n{val}")
                elif val is None:
                    lines.append(f"  {key}: null")
                elif isinstance(val, bool):
                    lines.append(f"  {key}: {'true' if val else 'false'}")
                else:
                    lines.append(f"  {key}: {val}")
        return "\n".join(lines) + "\n"

