"""YAML renderer — standard-library only (no PyYAML dependency)."""

from plugins import PluginError, Renderer, register


def _yaml_value(v):
    """Return a YAML-safe string representation of a scalar value."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return str(v)
    s = str(v)
    if s == "":
        return '""'
    if s.lower() in ("null", "true", "false", "yes", "no", "on", "off"):
        return f'"{s}"'
    special_chars = ":{}[]&*?|->!%@`," + "#"
    if any(c in s for c in special_chars):
        return f'"{s}"'
    if s.startswith(('"', "'", '{', '[', ' ', '\t')):
        return f'"{s}"'
    return s


def _yaml_dump(rows):
    """Serialize a list of flat dicts to a YAML string."""
    lines = []
    for row in rows:
        lines.append("-")
        for key, value in row.items():
            lines.append(f"  {key}: {_yaml_value(value)}")
    return "\n".join(lines) + "\n"


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        return _yaml_dump(rows)

